using System.Data;
using Essco.Application.Billing;
using Essco.Domain.Billing;
using Microsoft.Data.SqlClient;
namespace Essco.Infrastructure.Data;

public sealed class SqlServerElectronicInvoiceRepository(string connectionString, int timeout) : IElectronicInvoiceRepository
{
    public async ValueTask<IReadOnlyCollection<ElectronicInvoice>> ListAsync(ElectronicInvoiceFilter f, CancellationToken t) { await using var c = await Open(t); await using var cmd = Cmd("", c); var w = new List<string>(); if (!string.IsNullOrWhiteSpace(f.Search)) { w.Add("([DocNum]=@Search OR [CodCliente]=@Search OR [Receptor_Nombre] LIKE @Like OR [Clave]=@Search)"); P(cmd, "@Search", 100, f.Search); P(cmd, "@Like", 300, $"%{f.Search.Trim()}%"); } if (f.From is not null) { w.Add("[DocDate]>=@From"); cmd.Parameters.Add("@From", SqlDbType.Date).Value = f.From.Value.ToDateTime(TimeOnly.MinValue); } if (f.To is not null) { w.Add("[DocDate]<DATEADD(day,1,@To)"); cmd.Parameters.Add("@To", SqlDbType.Date).Value = f.To.Value.ToDateTime(TimeOnly.MinValue); } if (!string.IsNullOrWhiteSpace(f.HaciendaStatus)) { w.Add("[MH_Status]=@Mh"); P(cmd, "@Mh", 50, f.HaciendaStatus); } cmd.CommandText = $"SELECT TOP(500) [DocNum],[Clave],[Consecutivo],[DocDate],[DocDueDate],[CodCliente],[Receptor_Nombre],[Receptor_Numero],[CodigoMoneda],[TipoCambio],[DocSubTotal],[DocTotalDescuento],[DocTotalImpuesto],[DocTotal],[Status],[MH_Status],[MH_Message],[Comments] FROM [dbo].[CE_FE]{(w.Count == 0 ? "" : " WHERE " + string.Join(" AND ", w))} ORDER BY [DocDate] DESC,[DocNum] DESC"; var a = new List<ElectronicInvoice>(); await using var r = await cmd.ExecuteReaderAsync(t); while (await r.ReadAsync(t)) a.Add(Map(r, [])); return a; }
    public async ValueTask<ElectronicInvoice?> GetAsync(string n, CancellationToken t) { await using var c = await Open(t); ElectronicInvoice? h; await using (var cmd = Cmd("SELECT TOP(1) [DocNum],[Clave],[Consecutivo],[DocDate],[DocDueDate],[CodCliente],[Receptor_Nombre],[Receptor_Numero],[CodigoMoneda],[TipoCambio],[DocSubTotal],[DocTotalDescuento],[DocTotalImpuesto],[DocTotal],[Status],[MH_Status],[MH_Message],[Comments] FROM [dbo].[CE_FE] WHERE [DocNum]=@Number", c)) { P(cmd, "@Number", 100, n); await using var r = await cmd.ExecuteReaderAsync(t); h = await r.ReadAsync(t) ? Map(r, []) : null; } if (h is null) return null; var lines = new List<ElectronicInvoiceLine>(); await using (var cmd = Cmd("SELECT [NumLinea],[ItemCode],[ItemName],[UnidadMedida],[Cantidad],[PrecioUnitario],[Descuento_Monto],[Impuesto_Monto],[Total],[Cabys],[CodigoTarifa],[Exoneracion_PorcentajeCompra],[Exoneracion_MontoImpuesto] FROM [dbo].[CE_FE1] WHERE [DocNum]=@Number ORDER BY [NumLinea]", c)) { P(cmd, "@Number", 100, n); await using var r = await cmd.ExecuteReaderAsync(t); while (await r.ReadAsync(t)) lines.Add(new(Convert.ToInt32(r["NumLinea"]), S(r, "ItemCode"), S(r, "ItemName"), S(r, "UnidadMedida"), D(r, "Cantidad"), D(r, "PrecioUnitario"), D(r, "Descuento_Monto"), D(r, "Impuesto_Monto"), D(r, "Total"), S(r, "Cabys"), S(r, "CodigoTarifa"), D(r, "Exoneracion_PorcentajeCompra"), D(r, "Exoneracion_MontoImpuesto"))); } return h with { Lines = lines }; }
    private static ElectronicInvoice Map(SqlDataReader r, IReadOnlyCollection<ElectronicInvoiceLine> l) => new(S(r, "DocNum"), S(r, "Clave"), S(r, "Consecutivo"), Date(r, "DocDate"), Date(r, "DocDueDate"), S(r, "CodCliente"), S(r, "Receptor_Nombre"), S(r, "Receptor_Numero"), S(r, "CodigoMoneda"), D(r, "TipoCambio"), D(r, "DocSubTotal"), D(r, "DocTotalDescuento"), D(r, "DocTotalImpuesto"), D(r, "DocTotal"), S(r, "Status"), S(r, "MH_Status"), S(r, "MH_Message"), S(r, "Comments"), l); private static string S(SqlDataReader r, string n) => r[n] is DBNull ? "" : Convert.ToString(r[n])?.Trim() ?? ""; private static decimal D(SqlDataReader r, string n) => r[n] is DBNull ? 0 : Convert.ToDecimal(r[n]); private static DateOnly Date(SqlDataReader r, string n) => r[n] is DBNull ? default : DateOnly.FromDateTime(Convert.ToDateTime(r[n])); private static void P(SqlCommand c, string n, int z, string? v) => c.Parameters.Add(n, SqlDbType.NVarChar, z).Value = v?.Trim() ?? ""; private async ValueTask<SqlConnection> Open(CancellationToken t) { var c = new SqlConnection(connectionString); await c.OpenAsync(t); return c; }
    private SqlCommand Cmd(string s, SqlConnection c) => new(s, c) { CommandTimeout = timeout };
}
